properties.query:
// Detects CMSTP UAC Bypass 
// Reference: hxxps[://]github[.]com/SigmaHQ/sigma/blob/master/rules/windows/process_creation/proc_creation_win_uac_bypass_cmstp_com_object_access.yml
// Note, rule originally includes an integrity level check which has been excluded here. Use the link above for more.
let Parent_Process = dynamic(["DllHost.exe"]);
let cmd_any = dynamic(["/Processid:{3E5FC7F9-9A51-4367-9063-A120244FBEC7}","/Processid:{3E000D72-A845-4CD9-BD83-80C07C3B881F}","/Processid:{BD54C901-076B-434E-B6C7-17C531F4AB41}","/Processid:{D2E7041B-2927-42FB-8E9F-7CE93B6DC937}","/Processid:{E9495B87-D950-4AB5-87A5-FF6D70BF3E90}"]);
_Im_ProcessCreate(commandline_has_any=cmd_any,parentprocess_has_any=Parent_Process)
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
